/* Part 214 (round V, track 11): inventory that keeps track of everything, and a file's alt text. Run after part 78. Statements are separated by a blank line; supabase/sql/run-now/214_inventory_and_files.sql is the same statements, one per line. No existing row changes and nothing is dropped except a CHECK replaced by a wider one. Until it runs, the app adjusts stock and moves transfers the way it did before (step by step), keeps one low stock line per product, says who changed stock only as "You" or "Storelib", and says alt text needs this part. Safe to run again. */
/* 1. A low stock line per variant. NULL: the product's own line, else the shop's default. */
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS low_stock_threshold integer CHECK (low_stock_threshold IS NULL OR low_stock_threshold BETWEEN 0 AND 1000000);
/* 2. The history says who: the signed in person (the owner or a team member) behind a manual change. No foreign key, so a member who leaves the team stays in the history. */
ALTER TABLE public.inventory_movements ADD COLUMN IF NOT EXISTS actor_user_id uuid;
CREATE INDEX IF NOT EXISTS inventory_movements_ref_idx ON public.inventory_movements (creator_id, ref_type, ref_id) WHERE ref_type IS NOT NULL;
/* 3. Two more reasons: Other (a manual change that fits no other reason) and a transfer cancelled on its way, whose units go back to where they left. The old list is kept whole inside the new one. */
ALTER TABLE public.inventory_movements DROP CONSTRAINT IF EXISTS inventory_movements_reason_check;
ALTER TABLE public.inventory_movements ADD CONSTRAINT inventory_movements_reason_check CHECK (reason IN ('initial', 'received', 'correction', 'count', 'damaged', 'theft_or_loss', 'promotion_or_donation', 'returned_restock', 'sale_fulfilled', 'order_reserved', 'reservation_released', 'order_cancelled', 'transfer_out', 'transfer_in', 'incoming_added', 'incoming_cancelled', 'provider_sync', 'other', 'transfer_cancelled'));
/* 4. The history is append only. A row is never edited or deleted; the one change allowed is a product, location or shop that is deleted clearing its own id (ON DELETE SET NULL), so the history outlives what it was about. */
CREATE OR REPLACE FUNCTION public.inventory_movements_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'inventory_movements is append only' USING ERRCODE = 'P0001'; END IF; IF (to_jsonb(NEW) - 'creator_id' - 'variant_id' - 'location_id') IS DISTINCT FROM (to_jsonb(OLD) - 'creator_id' - 'variant_id' - 'location_id') OR (NEW.creator_id IS NOT NULL AND NEW.creator_id IS DISTINCT FROM OLD.creator_id) OR (NEW.variant_id IS NOT NULL AND NEW.variant_id IS DISTINCT FROM OLD.variant_id) OR (NEW.location_id IS NOT NULL AND NEW.location_id IS DISTINCT FROM OLD.location_id) THEN RAISE EXCEPTION 'inventory_movements is append only' USING ERRCODE = 'P0001'; END IF; RETURN NEW; END $f$;
DROP TRIGGER IF EXISTS inventory_movements_append_only ON public.inventory_movements;
CREATE TRIGGER inventory_movements_append_only BEFORE UPDATE OR DELETE ON public.inventory_movements FOR EACH ROW EXECUTE FUNCTION public.inventory_movements_append_only();
/* 5. One stock change, written down with who made it. The same as part 78's physical_inventory_apply, plus the person, and the key checked again once the level is locked, so two presses at the same moment are one change. */
CREATE OR REPLACE FUNCTION public.physical_inventory_move(p_creator uuid, p_variant uuid, p_location uuid, p_on_hand integer, p_committed integer, p_incoming integer, p_reason text, p_ref_type text, p_ref_id text, p_key text, p_actor text, p_actor_user uuid, p_note text, p_guard boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE lvl public.inventory_levels%ROWTYPE; owner uuid; loc_owner uuid; n_on integer; n_com integer; n_inc integer; BEGIN SELECT p.creator_id INTO owner FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = p_variant; SELECT creator_id INTO loc_owner FROM public.inventory_locations WHERE id = p_location; IF owner IS NULL OR owner IS DISTINCT FROM p_creator OR loc_owner IS NULL OR loc_owner IS DISTINCT FROM p_creator THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (p_variant, p_location, p_creator) ON CONFLICT (variant_id, location_id) DO NOTHING; SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = p_variant AND location_id = p_location FOR UPDATE; IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.inventory_movements WHERE idempotency_key = p_key) THEN RETURN jsonb_build_object('applied', false, 'repeat', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.on_hand - lvl.committed); END IF; n_on := lvl.on_hand + coalesce(p_on_hand, 0); n_com := greatest(lvl.committed + coalesce(p_committed, 0), 0); n_inc := greatest(lvl.incoming + coalesce(p_incoming, 0), 0); IF p_guard AND (n_on - n_com) < 0 AND (coalesce(p_on_hand, 0) < 0 OR coalesce(p_committed, 0) > 0) THEN RETURN jsonb_build_object('applied', false, 'error', 'insufficient', 'available', lvl.on_hand - lvl.committed, 'on_hand', lvl.on_hand); END IF; UPDATE public.inventory_levels SET on_hand = n_on, committed = n_com, incoming = n_inc, updated_at = now() WHERE variant_id = p_variant AND location_id = p_location; INSERT INTO public.inventory_movements (creator_id, variant_id, location_id, delta_on_hand, delta_committed, delta_incoming, on_hand_after, committed_after, incoming_after, reason, ref_type, ref_id, note, actor, actor_user_id, idempotency_key) VALUES (p_creator, p_variant, p_location, n_on - lvl.on_hand, n_com - lvl.committed, n_inc - lvl.incoming, n_on, n_com, n_inc, p_reason, p_ref_type, p_ref_id, left(p_note, 500), coalesce(p_actor, 'system'), p_actor_user, p_key); RETURN jsonb_build_object('applied', true, 'on_hand', n_on, 'committed', n_com, 'incoming', n_inc, 'available', n_on - n_com, 'on_hand_before', lvl.on_hand, 'incoming_before', lvl.incoming); END $f$;
/* 6. Adjust: add, remove or set on hand (or what is on order), worked out under the level's lock, so a count typed while an order ships is still the count. Taking away more than is on hand is refused; a reason outside the manual list is a correction. */
CREATE OR REPLACE FUNCTION public.physical_inventory_adjust(p_creator uuid, p_variant uuid, p_location uuid, p_field text, p_mode text, p_quantity integer, p_reason text, p_note text, p_key text, p_actor_user uuid, p_ref_type text) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE lvl public.inventory_levels%ROWTYPE; owner uuid; loc_owner uuid; cur integer; delta integer; why text; done jsonb; BEGIN IF p_field IS NULL OR p_field NOT IN ('on_hand', 'incoming') OR p_mode IS NULL OR p_mode NOT IN ('add', 'remove', 'set') THEN RETURN jsonb_build_object('applied', false, 'error', 'bad_input'); END IF; IF p_quantity IS NULL OR p_quantity < 0 OR p_quantity > 1000000 THEN RETURN jsonb_build_object('applied', false, 'error', 'bad_quantity'); END IF; SELECT p.creator_id INTO owner FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = p_variant; SELECT creator_id INTO loc_owner FROM public.inventory_locations WHERE id = p_location; IF owner IS NULL OR owner IS DISTINCT FROM p_creator OR loc_owner IS NULL OR loc_owner IS DISTINCT FROM p_creator THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; INSERT INTO public.inventory_levels (variant_id, location_id, creator_id) VALUES (p_variant, p_location, p_creator) ON CONFLICT (variant_id, location_id) DO NOTHING; SELECT * INTO lvl FROM public.inventory_levels WHERE variant_id = p_variant AND location_id = p_location FOR UPDATE; IF p_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.inventory_movements WHERE idempotency_key = p_key) THEN RETURN jsonb_build_object('applied', false, 'repeat', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.on_hand - lvl.committed); END IF; cur := CASE WHEN p_field = 'incoming' THEN lvl.incoming ELSE lvl.on_hand END; delta := CASE p_mode WHEN 'add' THEN p_quantity WHEN 'remove' THEN -p_quantity ELSE p_quantity - cur END; IF delta < 0 AND cur + delta < 0 THEN RETURN jsonb_build_object('applied', false, 'error', 'below_zero', 'current', cur); END IF; IF delta = 0 THEN RETURN jsonb_build_object('applied', false, 'unchanged', true, 'on_hand', lvl.on_hand, 'committed', lvl.committed, 'incoming', lvl.incoming, 'available', lvl.on_hand - lvl.committed, 'before', cur, 'after', cur); END IF; IF p_field = 'incoming' THEN why := CASE WHEN delta > 0 THEN 'incoming_added' ELSE 'incoming_cancelled' END; ELSIF p_reason IN ('received', 'correction', 'count', 'damaged', 'theft_or_loss', 'promotion_or_donation', 'returned_restock', 'other') THEN why := p_reason; ELSE why := 'correction'; END IF; done := public.physical_inventory_move(p_creator, p_variant, p_location, CASE WHEN p_field = 'on_hand' THEN delta ELSE 0 END, 0, CASE WHEN p_field = 'incoming' THEN delta ELSE 0 END, why, p_ref_type, NULL, p_key, 'creator', p_actor_user, p_note, false); RETURN done || jsonb_build_object('before', cur, 'after', cur + delta, 'delta', delta); END $f$;
/* 7. A transfer sent: every item leaves the origin and shows as incoming at the destination, all in one transaction. One item short and nothing moves. */
CREATE OR REPLACE FUNCTION public.physical_transfer_ship(p_creator uuid, p_transfer uuid, p_actor_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE t public.inventory_transfers%ROWTYPE; it record; r jsonb; n integer := 0; BEGIN SELECT * INTO t FROM public.inventory_transfers WHERE id = p_transfer AND creator_id = p_creator FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; IF t.status <> 'draft' THEN RETURN jsonb_build_object('applied', false, 'error', 'wrong_status', 'status', t.status); END IF; IF t.origin_location_id IS NULL OR t.destination_location_id IS NULL THEN RETURN jsonb_build_object('applied', false, 'error', 'no_location'); END IF; FOR it IN SELECT id, variant_id, quantity FROM public.inventory_transfer_items WHERE transfer_id = p_transfer AND variant_id IS NOT NULL ORDER BY variant_id LOOP r := public.physical_inventory_move(p_creator, it.variant_id, t.origin_location_id, -it.quantity, 0, 0, 'transfer_out', 'transfer', p_transfer::text, 'transfer_out:' || it.id, 'creator', p_actor_user, NULL, true); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_short:%:%', it.variant_id, greatest(coalesce((r->>'available')::integer, 0), 0) USING ERRCODE = 'P0001'; END IF; r := public.physical_inventory_move(p_creator, it.variant_id, t.destination_location_id, 0, 0, it.quantity, 'incoming_added', 'transfer', p_transfer::text, 'transfer_incoming:' || it.id, 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; n := n + 1; END LOOP; IF n = 0 THEN RETURN jsonb_build_object('applied', false, 'error', 'empty'); END IF; UPDATE public.inventory_transfers SET status = 'in_transit', shipped_at = now(), updated_at = now() WHERE id = p_transfer AND creator_id = p_creator; RETURN jsonb_build_object('applied', true, 'status', 'in_transit', 'items', n); END $f$;
/* 8. A transfer received, all or part: what arrived moves from incoming to on hand at the destination. More than is still on its way is taken as all of it. */
CREATE OR REPLACE FUNCTION public.physical_transfer_receive(p_creator uuid, p_transfer uuid, p_items jsonb, p_actor_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE t public.inventory_transfers%ROWTYPE; it record; want integer; r jsonb; got integer := 0; next_status text; BEGIN SELECT * INTO t FROM public.inventory_transfers WHERE id = p_transfer AND creator_id = p_creator FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; IF t.status NOT IN ('in_transit', 'partially_received') THEN RETURN jsonb_build_object('applied', false, 'error', 'wrong_status', 'status', t.status); END IF; IF t.destination_location_id IS NULL THEN RETURN jsonb_build_object('applied', false, 'error', 'no_location'); END IF; IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN RETURN jsonb_build_object('applied', false, 'error', 'bad_input'); END IF; FOR it IN SELECT id, variant_id, quantity, received_quantity FROM public.inventory_transfer_items WHERE transfer_id = p_transfer ORDER BY variant_id FOR UPDATE LOOP SELECT coalesce(sum(CASE WHEN (e->>'quantity') ~ '^[0-9]{1,7}$' THEN (e->>'quantity')::integer ELSE 0 END), 0)::integer INTO want FROM jsonb_array_elements(p_items) e WHERE e->>'item_id' = it.id::text; want := least(want, it.quantity - it.received_quantity); IF want <= 0 OR it.variant_id IS NULL THEN CONTINUE; END IF; r := public.physical_inventory_move(p_creator, it.variant_id, t.destination_location_id, want, 0, -want, 'transfer_in', 'transfer', p_transfer::text, 'transfer_in:' || it.id || ':' || (it.received_quantity + want), 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; UPDATE public.inventory_transfer_items SET received_quantity = received_quantity + want WHERE id = it.id; got := got + want; END LOOP; SELECT CASE WHEN bool_and(received_quantity >= quantity) THEN 'received' WHEN bool_or(received_quantity > 0) THEN 'partially_received' ELSE t.status END INTO next_status FROM public.inventory_transfer_items WHERE transfer_id = p_transfer; UPDATE public.inventory_transfers SET status = coalesce(next_status, t.status), received_at = CASE WHEN next_status = 'received' THEN now() ELSE received_at END, updated_at = now() WHERE id = p_transfer AND creator_id = p_creator; RETURN jsonb_build_object('applied', got > 0, 'status', coalesce(next_status, t.status), 'received', got); END $f$;
/* 9. A transfer cancelled. A draft only changes its status. One on its way gives back what has not arrived: on hand again at the origin, no longer incoming at the destination. What already arrived stays. */
CREATE OR REPLACE FUNCTION public.physical_transfer_cancel(p_creator uuid, p_transfer uuid, p_actor_user uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path = public AS $f$ DECLARE t public.inventory_transfers%ROWTYPE; it record; open_qty integer; r jsonb; back integer := 0; BEGIN SELECT * INTO t FROM public.inventory_transfers WHERE id = p_transfer AND creator_id = p_creator FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied', false, 'error', 'not_found'); END IF; IF t.status IN ('received', 'cancelled') THEN RETURN jsonb_build_object('applied', false, 'error', 'wrong_status', 'status', t.status); END IF; IF t.status <> 'draft' THEN FOR it IN SELECT id, variant_id, quantity, received_quantity FROM public.inventory_transfer_items WHERE transfer_id = p_transfer AND variant_id IS NOT NULL ORDER BY variant_id LOOP open_qty := it.quantity - it.received_quantity; IF open_qty <= 0 THEN CONTINUE; END IF; IF t.origin_location_id IS NOT NULL THEN r := public.physical_inventory_move(p_creator, it.variant_id, t.origin_location_id, open_qty, 0, 0, 'transfer_cancelled', 'transfer', p_transfer::text, 'transfer_cancel_out:' || it.id, 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; END IF; IF t.destination_location_id IS NOT NULL THEN r := public.physical_inventory_move(p_creator, it.variant_id, t.destination_location_id, 0, 0, -open_qty, 'incoming_cancelled', 'transfer', p_transfer::text, 'transfer_cancel_in:' || it.id, 'creator', p_actor_user, NULL, false); IF r ? 'error' THEN RAISE EXCEPTION 'transfer_failed:%', it.variant_id USING ERRCODE = 'P0001'; END IF; END IF; back := back + open_qty; END LOOP; END IF; UPDATE public.inventory_transfers SET status = 'cancelled', updated_at = now() WHERE id = p_transfer AND creator_id = p_creator; RETURN jsonb_build_object('applied', true, 'status', 'cancelled', 'returned', back); END $f$;
/* 10. The new functions are the server's alone, like part 78's. */
REVOKE ALL ON FUNCTION public.physical_inventory_move(uuid, uuid, uuid, integer, integer, integer, text, text, text, text, text, uuid, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_inventory_move(uuid, uuid, uuid, integer, integer, integer, text, text, text, text, text, uuid, text, boolean) TO service_role;
REVOKE ALL ON FUNCTION public.physical_inventory_adjust(uuid, uuid, uuid, text, text, integer, text, text, text, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_inventory_adjust(uuid, uuid, uuid, text, text, integer, text, text, text, uuid, text) TO service_role;
REVOKE ALL ON FUNCTION public.physical_transfer_ship(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_transfer_ship(uuid, uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_transfer_receive(uuid, uuid, jsonb, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_transfer_receive(uuid, uuid, jsonb, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.physical_transfer_cancel(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.physical_transfer_cancel(uuid, uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.inventory_movements_append_only() FROM PUBLIC, anon, authenticated;
/* 11. A file's alt text (Files), keyed by where the file is stored. Written by the server only, for the shop whose folder the path is in; the owner may read their own. */
CREATE TABLE IF NOT EXISTS public.file_details (bucket text NOT NULL CHECK (bucket IN ('store-builder-images', 'product-images')), path text NOT NULL CHECK (length(path) BETWEEN 3 AND 300), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, alt_text text CHECK (alt_text IS NULL OR length(alt_text) <= 500), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT file_details_pkey PRIMARY KEY (bucket, path));
CREATE INDEX IF NOT EXISTS file_details_creator_idx ON public.file_details (creator_id);
ALTER TABLE public.file_details ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_details FROM PUBLIC, anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.file_details FROM authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.file_details TO service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads file_details" ON public.file_details; CREATE POLICY "storelib owner reads file_details" ON public.file_details FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = file_details.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
notify pgrst, 'reload schema';
